1	import { IntroOverlay } from "../ui/IntroOverlay.js";
2	import { ScrollLock } from "../utils/ScrollLock.js";
3	import { Aria } from "../utils/Aria.js";
4	import { TextReveal } from "../animation/TextReveal.js";
5	import { BlockReveal } from "../animation/BlockReveal.js";
6	import { DOM_CONFIG } from "../config/dom.config.js";
7	import {
8	  INTRO_ACTION_COUNTDOWN_ORBIT,
9	  INTRO_ACTION_COUNTDOWN_SEQUENCE,
10	  INTRO_ACTION_STORY_SEQUENCE,
11	} from "../config/intro.config.js";
12	import type { GsapGlobal } from "../types/gsap.types.js";
13	import type {
14	  IntroFlowDomElements,
15	  IntroFlowRunOptions,
16	} from "../types/runtime.types.js";
17	
18	const MAIN_FLOW = DOM_CONFIG.keys.mainFlow;
19	const INTRO_ACTION_TRIGGER_SELECTOR =
20	  MAIN_FLOW?.introTrigger ?? '[data-intro-action="after-intro"]';
21	const INTRO_SECTION_SELECTOR = MAIN_FLOW?.introSection ?? ".no-main-intro";
22	const INTRO_ACTION_SECTION_SELECTOR =
23	  MAIN_FLOW?.introActionSection ?? ".no-main-intro-action";
24	const INTRO_TEXT_SELECTOR = MAIN_FLOW?.introText ?? ".no-main-intro__txt";
25	const INTRO_REVEAL_GROUP_SELECTOR =
26	  MAIN_FLOW?.introRevealGroups ??
27	  ".no-main-intro__txt--top, .no-main-intro__txt--bottom";
28	const INTRO_REVEAL_TEXT_SELECTOR =
29	  MAIN_FLOW?.introRevealText ??
30	  ".no-main-intro .no-main-intro__title .mask-target, .no-main-intro .no-main-intro__txt--top > .mask-target";
31	const INTRO_REVEAL_BUTTON_SELECTOR = INTRO_ACTION_TRIGGER_SELECTOR;
32	const INTRO_ACTION_CONTENT_SELECTOR =
33	  MAIN_FLOW?.introActionContent ?? ".no-main-intro-action__content";
34	const INTRO_ACTION_TEXT_SELECTOR =
35	  MAIN_FLOW?.introActionText ?? ".no-main-intro-action__content .mask-target";
36	const INTRO_ACTION_COUNTDOWN_SELECTOR =
37	  MAIN_FLOW?.introActionCountdown ?? ".no-main-intro-action__countdown";
38	const INTRO_ACTION_COUNTDOWN_VALUE_SELECTOR =
39	  MAIN_FLOW?.introActionCountdownValue ??
40	  ".no-main-intro-action__countdown-value";
41	const INTRO_ACTION_SKIP_SELECTOR =
42	  MAIN_FLOW?.introActionSkip ?? ".no-main-intro-action__skip";
43	const INTRO_ACTION_SKIP_VISIBLE_PROPS = {
44	  opacity: 1,
45	  y: 0,
46	  pointerEvents: "auto",
47	} as const;
48	const INTRO_ACTION_SKIP_HIDDEN_PROPS = {
49	  opacity: 0,
50	  y: 24,
51	  pointerEvents: "none",
52	} as const;
53	const INTRO_REVEAL_GROUP_DELAY = 0;
54	const INTRO_REVEAL_TEXT_DELAY = 0.1;
55	const INTRO_REVEAL_BUTTON_DELAY = 0.38;
56	export class IntroFlowRuntime {
57	  private _introActionHandler: ((event: Event) => void) | null = null;
58	  private _introActionSkipHandler: ((event: Event) => void) | null = null;
59	  private _dom: IntroFlowDomElements | null = null;
60	  private _releaseScrollLock: (() => void) | null = null;
61	
62	  async run(options: IntroFlowRunOptions): Promise<void> {
63	    const { introConfig, gsap, loadPromise } = options;
64	    this._dom = this._createDomElements(options.root);
65	    this._renderIntroActionCountdownOrbit();
66	
67	    this._primeIntroDomReveal(gsap);
68	    IntroOverlay.show();
69	    this._setSectionHidden(this._dom.introSection, false);
70	    this._setSectionHidden(this._dom.introActionSection, !options.showDebugDomState);
71	    if (options.showDebugDomState) this._showDebugDomState(gsap);
72	
73	    const introRunner = new IntroOverlay(introConfig);
74	    await introRunner
75	      .run({
76	        gsap,
77	        loadPromise,
78	      })
79	      .finally(() => introRunner.dispose());
80	
81	    if (options.disableScrollLock) this.releaseScrollLock();
82	    else this._acquireScrollLock({ pauseLenis: true });
83	    await options.onAfterIntroAutoplay?.();
84	    await this._playIntroDomReveal(gsap);
85	    options.onIntroDomRevealComplete?.();
86	    await this._waitForIntroAction(options);
87	    await options.onPreviewStart?.();
88	  }
89	
90	  dispose(): void {
91	    this.releaseScrollLock();
92	    this._unbindIntroActionTrigger();
93	    this._unbindIntroActionSkip();
94	    this._dom = null;
95	  }
96	
97	  releaseScrollLock(): void {
98	    this._releaseScrollLock?.();
99	    this._releaseScrollLock = null;
100	  }
101	
102	  async playIntroActionStorySequence(gsap: GsapGlobal | null): Promise<void> {
103	    const contents = this._getDom().introActionContents;
104	    if (contents.length === 0) return;
105	
106	    contents.forEach((content) => {
107	      BlockReveal.hide(content);
108	      TextReveal.setVisibleOff(content);
109	    });
110	
111	    await this._waitForStorySequenceStart(gsap);
112	
113	    for (const content of contents) {
114	      await this._playIntroActionStoryContent(content, gsap);
115	    }
116	  }
117	
118	  async playIntroActionCountdown(gsap: GsapGlobal | null): Promise<boolean> {
119	    const { introActionCountdown: countdown, introActionCountdownValue: value } =
120	      this._getDom();
121	    if (!countdown || !value) return false;
122	
123	    return await new Promise<boolean>((resolve) => {
124	      let isFinished = false;
125	      let timeoutId: number | null = null;
126	      let timeline: ReturnType<GsapGlobal["timeline"]> | null = null;
127	
128	      const finish = (skipped: boolean): void => {
129	        if (isFinished) return;
130	        isFinished = true;
131	        if (timeoutId != null) {
132	          window.clearTimeout(timeoutId);
133	          timeoutId = null;
134	        }
135	        timeline?.kill?.();
136	        this._blurIfFocused(this._getDom().introActionSkip);
137	        this._hideIntroActionSkip(gsap);
138	        this._unbindIntroActionSkip();
139	        if (gsap) {
140	          gsap.to(countdown, {
141	            autoAlpha: 0,
142	            scale: 0.94,
143	            duration: 0.32,
144	            ease: "power2.out",
145	            onComplete: () => resolve(skipped),
146	          });
147	          return;
148	        }
149	        countdown.style.transition =
150	          "opacity 0.32s ease, transform 0.32s ease";
151	        countdown.style.opacity = "0";
152	        countdown.style.transform = "scale(0.94)";
153	        window.setTimeout(() => resolve(skipped), 320);
154	      };
155	
156	      this._bindIntroActionSkip(() => finish(true));
157	      this._showIntroActionSkip(gsap);
158	
159	      if (!gsap) {
160	        const stepDuration =
161	          (INTRO_ACTION_COUNTDOWN_SEQUENCE.enterDuration +
162	            INTRO_ACTION_COUNTDOWN_SEQUENCE.holdDuration +
163	            INTRO_ACTION_COUNTDOWN_SEQUENCE.exitDuration +
164	            INTRO_ACTION_COUNTDOWN_SEQUENCE.gapDuration) *
165	          1000;
166	        countdown.style.opacity = "1";
167	
168	        const playStep = (index: number): void => {
169	          if (index >= INTRO_ACTION_COUNTDOWN_SEQUENCE.values.length) {
170	            finish(false);
171	            return;
172	          }
173	          value.textContent = INTRO_ACTION_COUNTDOWN_SEQUENCE.values[index];
174	          timeoutId = window.setTimeout(() => {
175	            playStep(index + 1);
176	          }, stepDuration);
177	        };
178	
179	        playStep(0);
180	        return;
181	      }
182	
183	      timeline = gsap.timeline({
184	        onStart: () => {
185	          gsap.set(countdown, { autoAlpha: 1, scale: 1 });
186	        },
187	        onComplete: () => {
188	          finish(false);
189	        },
190	      });
191	
192	      INTRO_ACTION_COUNTDOWN_SEQUENCE.values.forEach((countdownValue) => {
193	        timeline.set(value, {
194	          textContent: countdownValue,
195	          autoAlpha: 0,
196	          scale: INTRO_ACTION_COUNTDOWN_SEQUENCE.initialScale,
197	          filter: INTRO_ACTION_COUNTDOWN_SEQUENCE.initialBlur,
198	        });
199	        timeline.to(value, {
200	          autoAlpha: 1,
201	          scale: 1,
202	          filter: "blur(0px)",
203	          duration: INTRO_ACTION_COUNTDOWN_SEQUENCE.enterDuration,
204	          ease: INTRO_ACTION_COUNTDOWN_SEQUENCE.enterEase,
205	        });
206	        timeline
207	          .to(value, {
208	            autoAlpha: 1,
209	            scale: 1,
210	            duration: INTRO_ACTION_COUNTDOWN_SEQUENCE.holdDuration,
211	            ease: "none",
212	          })
213	          .to(value, {
214	            autoAlpha: 0,
215	            scale: INTRO_ACTION_COUNTDOWN_SEQUENCE.exitScale,
216	            filter: INTRO_ACTION_COUNTDOWN_SEQUENCE.exitBlur,
217	            duration: INTRO_ACTION_COUNTDOWN_SEQUENCE.exitDuration,
218	            ease: INTRO_ACTION_COUNTDOWN_SEQUENCE.exitEase,
219	          })
220	          .to(
221	            {},
222	            {
223	              duration: INTRO_ACTION_COUNTDOWN_SEQUENCE.gapDuration,
224	            },
225	          );
226	      });
227	    });
228	  }
