230	  private async _waitForIntroAction(options: IntroFlowRunOptions): Promise<void> {
231	    const { introActionTrigger: trigger } = this._getDom();
232	    if (!trigger) {
233	      await options.onIntroActionTransition?.();
234	      if (!options.keepIntroActionVisible) this._hideAllSections();
235	      return;
236	    }
237	
238	    await new Promise<void>((resolve) => {
239	      this._unbindIntroActionTrigger();
240	      this._introActionHandler = (event: Event) => {
241	        event.preventDefault();
242	        this._unbindIntroActionTrigger();
243	        void (async () => {
244	          try {
245	            await Promise.all([
246	              this._transitionIntroToAction(options.gsap),
247	              options.onIntroActionAutoplay?.(),
248	            ]);
249	          } finally {
250	            try {
251	              await options.onIntroActionTransition?.();
252	            } finally {
253	              if (!options.keepIntroActionVisible) this._hideAllSections();
254	              resolve();
255	            }
256	          }
257	        })();
258	      };
259	      trigger.addEventListener("click", this._introActionHandler, {
260	        passive: false,
261	      });
262	    });
263	  }
264	
265	  private _unbindIntroActionTrigger(): void {
266	    if (!this._introActionHandler) return;
267	    const { introActionTrigger: trigger } = this._getDom();
268	    if (trigger) {
269	      trigger.removeEventListener("click", this._introActionHandler);
270	    }
271	    this._introActionHandler = null;
272	  }
273	
274	  private _bindIntroActionSkip(onSkip: () => void): void {
275	    this._unbindIntroActionSkip();
276	    const { introActionSkip: skip } = this._getDom();
277	    if (!skip) return;
278	    this._introActionSkipHandler = (event: Event) => {
279	      event.preventDefault();
280	      onSkip();
281	    };
282	    skip.addEventListener("click", this._introActionSkipHandler, {
283	      passive: false,
284	    });
285	  }
286	
287	  private _unbindIntroActionSkip(): void {
288	    if (!this._introActionSkipHandler) return;
289	    const { introActionSkip: skip } = this._getDom();
290	    if (skip) {
291	      skip.removeEventListener("click", this._introActionSkipHandler);
292	    }
293	    this._introActionSkipHandler = null;
294	  }
295	
296	  private _acquireScrollLock(options?: { pauseLenis?: boolean }): void {
297	    this.releaseScrollLock();
298	    this._releaseScrollLock = ScrollLock.lock(options);
299	  }
300	
301	  private _setSectionHidden(section: HTMLElement | null, hidden: boolean): void {
302	    if (!section) return;
303	    section.style.display = hidden ? "none" : "";
304	    Aria.setHidden(section, hidden);
305	  }
306	
307	  private _hideAllSections(): void {
308	    const dom = this._getDom();
309	    this._blurIfFocused(dom.introActionSkip);
310	    this._blurIfFocused(dom.introActionTrigger);
311	    this._setSectionHidden(dom.introSection, true);
312	    this._setSectionHidden(dom.introActionSection, true);
313	  }
314	
315	  private _blurIfFocused(element: HTMLElement | null): void {
316	    if (!element) return;
317	    const activeElement = document.activeElement;
318	    if (activeElement !== element) return;
319	    element.blur();
320	  }
321	
322	  private _primeIntroDomReveal(gsap: GsapGlobal): void {
323	    BlockReveal.hide(INTRO_REVEAL_GROUP_SELECTOR);
324	    this._setIntroRevealButtonState(false, gsap);
325	    TextReveal.setVisibleOff(INTRO_REVEAL_TEXT_SELECTOR);
326	    BlockReveal.hide(INTRO_ACTION_CONTENT_SELECTOR);
327	    TextReveal.setVisibleOff(INTRO_ACTION_TEXT_SELECTOR);
328	    this._setIntroActionSkipState(false, gsap);
329	    gsap.set(INTRO_ACTION_COUNTDOWN_SELECTOR, {
330	      autoAlpha: 0,
331	      willChange: "opacity",
332	    });
333	    gsap.set(INTRO_ACTION_COUNTDOWN_VALUE_SELECTOR, {
334	      autoAlpha: 0,
335	      scale: INTRO_ACTION_COUNTDOWN_SEQUENCE.initialScale,
336	      filter: INTRO_ACTION_COUNTDOWN_SEQUENCE.initialBlur,
337	      willChange: "transform, opacity, filter",
338	    });
339	    gsap.set(
340	      [
341	        INTRO_REVEAL_GROUP_SELECTOR,
342	        INTRO_REVEAL_BUTTON_SELECTOR,
343	        INTRO_ACTION_CONTENT_SELECTOR,
344	      ],
345	      {
346	        willChange: "transform, opacity, filter",
347	      },
348	    );
349	    gsap.set(INTRO_ACTION_SKIP_SELECTOR, {
350	      willChange: "opacity",
351	    });
352	    gsap.set([INTRO_REVEAL_TEXT_SELECTOR, INTRO_ACTION_TEXT_SELECTOR], {
353	      willChange: "transform, opacity, filter",
354	    });
355	  }
356	
357	  private async _playIntroDomReveal(gsap: GsapGlobal): Promise<void> {
358	    await new Promise<void>((resolve) => {
359	      const timeline = gsap.timeline({ paused: true });
360	      timeline
361	        .add(() => BlockReveal.reveal(INTRO_REVEAL_GROUP_SELECTOR), INTRO_REVEAL_GROUP_DELAY)
362	        .add(() => TextReveal.setVisibleOn(INTRO_REVEAL_TEXT_SELECTOR), INTRO_REVEAL_TEXT_DELAY)
363	        .add(
364	          () => this._setIntroRevealButtonState(true, gsap),
365	          INTRO_REVEAL_BUTTON_DELAY,
366	        )
367	        .add(() => resolve(), INTRO_REVEAL_BUTTON_DELAY + 0.9);
368	      timeline.play();
369	    });
370	  }
371	
372	  private _showDebugDomState(gsap: GsapGlobal | null): void {
373	    BlockReveal.reveal(INTRO_REVEAL_GROUP_SELECTOR);
374	    TextReveal.setVisibleOn(INTRO_REVEAL_TEXT_SELECTOR);
375	    this._setIntroRevealButtonState(true, gsap);
376	    BlockReveal.reveal(INTRO_ACTION_CONTENT_SELECTOR);
377	    TextReveal.setVisibleOn(INTRO_ACTION_TEXT_SELECTOR);
378	    this._setIntroActionSkipState(true, gsap);
379	
380	    const { introActionCountdown: countdown, introActionCountdownValue: value } =
381	      this._getDom();
382	    if (!countdown || !value) return;
383	
384	    if (!gsap) {
385	      countdown.style.opacity = "1";
386	      countdown.style.visibility = "visible";
387	      countdown.style.transform = "scale(1)";
388	      value.style.opacity = "1";
389	      value.style.visibility = "visible";
390	      value.style.filter = "blur(0px)";
391	      value.style.transform = "scale(1)";
392	      return;
393	    }
394	
395	    gsap.set(countdown, {
396	      autoAlpha: 1,
397	      scale: 1,
398	      clearProps: "display",
399	    });
400	    gsap.set(value, {
401	      autoAlpha: 1,
402	      scale: 1,
403	      filter: "blur(0px)",
404	    });
405	  }
406	
407	  private async _transitionIntroToAction(gsap: GsapGlobal): Promise<void> {
408	    const dom = this._getDom();
409	    const introText = dom.introText;
410	    if (!introText) {
411	      this._setSectionHidden(dom.introSection, true);
412	      this._setSectionHidden(dom.introActionSection, false);
413	      return;
414	    }
415	
416	    await new Promise<void>((resolve) => {
417	      BlockReveal.hide(INTRO_REVEAL_GROUP_SELECTOR);
418	      this._setIntroRevealButtonState(false, gsap);
419	      TextReveal.setVisibleOff(INTRO_REVEAL_TEXT_SELECTOR);
420	      const delayedTween = gsap.delayedCall?.(0.64, resolve);
421	      if (delayedTween) return;
422	      window.setTimeout(resolve, 640);
423	    });
424	
425	    this._setSectionHidden(dom.introSection, true);
426	    this._setSectionHidden(dom.introActionSection, false);
427	    window.scrollTo({ top: 0, behavior: "auto" });
428	  }
