430	  private async _playIntroActionStoryContent(
431	    content: HTMLElement,
432	    gsap: GsapGlobal | null,
433	  ): Promise<void> {
434	    if (!gsap) {
435	      BlockReveal.reveal(content);
436	      TextReveal.setVisibleOn(content);
437	      await new Promise<void>((resolve) => {
438	        window.setTimeout(
439	          resolve,
440	          (INTRO_ACTION_STORY_SEQUENCE.enterDuration +
441	            INTRO_ACTION_STORY_SEQUENCE.holdDuration +
442	            INTRO_ACTION_STORY_SEQUENCE.exitDuration) *
443	            1000,
444	        );
445	      });
446	      TextReveal.setVisibleOff(content);
447	      BlockReveal.hide(content);
448	      return;
449	    }
450	
451	    await new Promise<void>((resolve) => {
452	      gsap.set(content, {
453	        autoAlpha: 0,
454	        y: INTRO_ACTION_STORY_SEQUENCE.initialOffsetY,
455	        filter: INTRO_ACTION_STORY_SEQUENCE.initialBlur,
456	      });
457	      const timeline = gsap.timeline({
458	        onStart: () => {
459	          BlockReveal.reveal(content);
460	          TextReveal.setVisibleOn(content);
461	        },
462	        onComplete: () => {
463	          TextReveal.setVisibleOff(content);
464	          BlockReveal.hide(content);
465	          resolve();
466	        },
467	      });
468	      timeline
469	        .to(content, {
470	          autoAlpha: 1,
471	          y: 0,
472	          filter: "blur(0px)",
473	          duration: INTRO_ACTION_STORY_SEQUENCE.enterDuration,
474	          ease: INTRO_ACTION_STORY_SEQUENCE.enterEase,
475	        })
476	        .to(content, {
477	          autoAlpha: 1,
478	          y: 0,
479	          duration: INTRO_ACTION_STORY_SEQUENCE.holdDuration,
480	          ease: INTRO_ACTION_STORY_SEQUENCE.holdEase,
481	        })
482	        .to(content, {
483	          autoAlpha: 0,
484	          y: INTRO_ACTION_STORY_SEQUENCE.exitOffsetY,
485	          filter: INTRO_ACTION_STORY_SEQUENCE.exitBlur,
486	          duration: INTRO_ACTION_STORY_SEQUENCE.exitDuration,
487	          ease: INTRO_ACTION_STORY_SEQUENCE.exitEase,
488	        });
489	    });
490	  }
491	
492	  private async _waitForStorySequenceStart(
493	    gsap: GsapGlobal | null,
494	  ): Promise<void> {
495	    if (!gsap) {
496	      await new Promise<void>((resolve) => {
497	        window.setTimeout(resolve, INTRO_ACTION_STORY_SEQUENCE.startDelay * 1000);
498	      });
499	      return;
500	    }
501	    await new Promise<void>((resolve) => {
502	      const delayedTween = gsap.delayedCall?.(
503	        INTRO_ACTION_STORY_SEQUENCE.startDelay,
504	        resolve,
505	      );
506	      if (delayedTween) return;
507	      window.setTimeout(resolve, INTRO_ACTION_STORY_SEQUENCE.startDelay * 1000);
508	    });
509	  }
510	
511	  private _showIntroActionSkip(gsap: GsapGlobal | null): void {
512	    const { introActionSkip: skip } = this._getDom();
513	    if (!skip) return;
514	    this._setIntroActionSkipState(true, gsap);
515	  }
516	
517	  private _hideIntroActionSkip(gsap: GsapGlobal | null): void {
518	    const { introActionSkip: skip } = this._getDom();
519	    if (!skip) return;
520	    this._setIntroActionSkipState(false, gsap);
521	  }
522	
523	  private _setIntroActionSkipState(
524	    visible: boolean,
525	    gsap: GsapGlobal | null,
526	  ): void {
527	    const { introActionSkip: skip } = this._getDom();
528	    if (!skip) return;
529	
530	    if (visible) {
531	      Aria.setHidden(skip, false);
532	      skip.removeAttribute("inert");
533	      skip.tabIndex = 0;
534	    } else {
535	      this._blurIfFocused(skip);
536	      skip.setAttribute("inert", "");
537	      skip.tabIndex = -1;
538	    }
539	
540	    if (!gsap) {
541	      skip.style.opacity = visible ? "1" : "0";
542	      skip.style.pointerEvents = visible ? "auto" : "none";
543	      skip.style.transform = visible
544	        ? "translateX(-50%) translateY(0)"
545	        : "translateX(-50%) translateY(24px)";
546	      if (!visible) {
547	        Aria.setHidden(skip, true);
548	      }
549	      return;
550	    }
551	
552	    gsap.to(skip, {
553	      ...(visible
554	        ? INTRO_ACTION_SKIP_VISIBLE_PROPS
555	        : INTRO_ACTION_SKIP_HIDDEN_PROPS),
556	      onComplete: () => {
557	        if (!visible) {
558	          Aria.setHidden(skip, true);
559	        }
560	      },
561	    });
562	  }
563	
564	  private _setIntroRevealButtonState(
565	    visible: boolean,
566	    gsap: GsapGlobal | null,
567	  ): void {
568	    const { introActionTrigger: trigger } = this._getDom();
569	    if (!trigger) return;
570	
571	    if (!gsap) {
572	      trigger.style.opacity = visible ? "1" : "0";
573	      trigger.style.pointerEvents = visible ? "auto" : "none";
574	      trigger.style.transform = visible
575	        ? "translate3d(0, 0, 0)"
576	        : "translate3d(0, 24px, 0)";
577	      return;
578	    }
579	
580	    gsap.killTweensOf?.(trigger);
581	    if (!visible) {
582	      gsap.set(trigger, {
583	        opacity: 0,
584	        y: 24,
585	        pointerEvents: "none",
586	      });
587	      return;
588	    }
589	
590	    gsap.to(trigger, {
591	      opacity: 1,
592	      y: 0,
593	      pointerEvents: "auto",
594	      duration: 0.72,
595	      ease: "power3.out",
596	    });
597	  }
598	
599	  private _getDom(): IntroFlowDomElements {
600	    this._dom ??= this._createDomElements();
601	    return this._dom;
602	  }
603	
604	  private _renderIntroActionCountdownOrbit(): void {
605	    const { introActionCountdownOrbit: orbit } = this._getDom();
606	    if (!orbit) return;
607	    orbit.replaceChildren();
608	    const fragment = document.createDocumentFragment();
609	    const markerCount = INTRO_ACTION_COUNTDOWN_ORBIT.markerCount;
610	    const loopDuration =
611	      INTRO_ACTION_COUNTDOWN_SEQUENCE.enterDuration +
612	      INTRO_ACTION_COUNTDOWN_SEQUENCE.holdDuration +
613	      INTRO_ACTION_COUNTDOWN_SEQUENCE.exitDuration +
